import { McpServer } from "@modelcontextprotocol/server";
import { z } from "zod";
import type { BrowserSession } from "../browser/session.js";

const INSTRUCTIONS = [
  "browser-chan controls a persistent Chromium profile that is already logged in. Never ask the user for credentials.",
  "Call browser_snapshot first to read the page and obtain element refs such as e1.",
  "Element refs are regenerated by every snapshot. Use refs from the snapshot returned by the previous action; a page action returns a new snapshot for the next action.",
  "Prefer browser_navigate, browser_snapshot, browser_click, browser_type, browser_select, browser_press_key and browser_wait_for. Use browser_evaluate only when the DOM snapshot is insufficient.",
].join("\n");

const textContent = (text: string) => ({
  content: [{ type: "text" as const, text }],
});

export const createBrowserMcpServer = (
  session: BrowserSession,
  version: string,
): McpServer => {
  const server = new McpServer(
    { name: "browser-chan", version },
    { instructions: INSTRUCTIONS },
  );

  server.registerTool(
    "browser_navigate",
    {
      description:
        "Navigate the active tab to an http or https URL and return a fresh page snapshot.",
      inputSchema: z.object({ url: z.string().url() }),
    },
    async ({ url }) => textContent(await session.navigate(url)),
  );

  server.registerTool(
    "browser_snapshot",
    {
      description:
        "Return the current page URL, title, visible text and interactive elements with fresh element refs.",
      inputSchema: z.object({}),
    },
    async () => textContent(await session.snapshot()),
  );

  server.registerTool(
    "browser_click",
    {
      description:
        "Click an element by ref from the snapshot returned by the previous action. Use refs from the snapshot this action returns for the next action.",
      inputSchema: z.object({ ref: z.string() }),
    },
    async ({ ref }) => textContent(await session.click(ref)),
  );

  server.registerTool(
    "browser_type",
    {
      description:
        "Fill an input or textarea by ref from the latest snapshot, optionally pressing Enter.",
      inputSchema: z.object({
        ref: z.string(),
        text: z.string(),
        submit: z.boolean().optional(),
      }),
    },
    async ({ ref, text, submit }) =>
      textContent(await session.type(ref, text, submit)),
  );

  server.registerTool(
    "browser_select",
    {
      description:
        "Select one or more option values in a select element by ref from the latest snapshot.",
      inputSchema: z.object({ ref: z.string(), values: z.array(z.string()) }),
    },
    async ({ ref, values }) => textContent(await session.select(ref, values)),
  );

  server.registerTool(
    "browser_press_key",
    {
      description:
        "Press a keyboard key on the active page, for example Enter, Tab or Escape.",
      inputSchema: z.object({ key: z.string() }),
    },
    async ({ key }) => textContent(await session.pressKey(key)),
  );

  server.registerTool(
    "browser_wait_for",
    {
      description:
        "Wait until the visible page text contains the given string, then return a fresh snapshot.",
      inputSchema: z.object({
        text: z.string(),
        timeoutMs: z.number().int().positive().optional(),
      }),
    },
    async ({ text, timeoutMs }) =>
      textContent(await session.waitFor(text, timeoutMs)),
  );

  server.registerTool(
    "browser_evaluate",
    {
      description:
        "Evaluate a JavaScript expression in the active page and return its JSON result. Use only when a snapshot is insufficient.",
      inputSchema: z.object({ expression: z.string() }),
    },
    async ({ expression }) => textContent(await session.evaluate(expression)),
  );

  server.registerTool(
    "browser_screenshot",
    {
      description: "Capture a PNG screenshot of the active page.",
      inputSchema: z.object({ fullPage: z.boolean().optional() }),
    },
    async ({ fullPage }) => {
      const image = await session.screenshot(fullPage);
      return {
        content: [
          {
            type: "image" as const,
            data: image.toString("base64"),
            mimeType: "image/png",
          },
          { type: "text" as const, text: "Captured a PNG screenshot." },
        ],
      };
    },
  );

  server.registerTool(
    "browser_tabs",
    {
      description:
        "List, open, select or close browser tabs. Tab indexes are 1-based and returned as JSON.",
      inputSchema: z.object({
        action: z.enum(["list", "new", "select", "close"]),
        index: z.number().int().positive().optional(),
        url: z.string().optional(),
      }),
    },
    async ({ action, index, url }) =>
      textContent(JSON.stringify(await session.tabs(action, index, url))),
  );

  server.registerTool(
    "browser_close",
    {
      description:
        "Close the browser context. The next operation launches it again from the persistent profile.",
      inputSchema: z.object({}),
    },
    async () => {
      await session.closeBrowser();
      return textContent("Browser closed.");
    },
  );

  return server;
};
